using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "DrawPoolDiscardMouseKeyboardAction", menuName = "Data/Battle/Actions/DrawPoolDiscardMouseKeyboard Action")]
public class DrawPoolDiscardMouseKeyboardAction : Action
{
	[SerializeField]
	private TransformReference diceBagButtonTransformReference;

	[SerializeField]
	private TransformReference discardButtonTransformReference;

	public override void OnStartState()
	{
	}

	public override void OnEndState()
	{
	}

	public override void Execute(float d)
	{
		base.inputManager.GetUIShortcutInput(base.inputManager.GetDrawPoolButtonUp(), delegate
		{
			diceBagButtonTransformReference.value.GetComponent<DiceBagDiscardButton>().OpenDicePanel();
		});
		base.inputManager.GetUIShortcutInput(base.inputManager.GetDiscardButtonUp(), delegate
		{
			discardButtonTransformReference.value.GetComponentInParent<DiceBagDiscardButton>().OpenDicePanel();
		});
	}
}
